'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { Plus, Edit, Trash2 } from 'lucide-react';

interface Article {
  id: string;
  documentId: string;
  title: string;
  slug: string;
  summary?: string;
  review_status: 'draft' | 'pending' | 'published' | 'rejected';
  publish_time?: string;
}

export default function ArticlesPage() {
  const [articles, setArticles] = useState<Article[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchArticles = async () => {
    try {
      setError(null);
      const response = await api.getArticles('?populate=category&sort=publish_time:desc');

      // 显式类型守卫 + 类型断言（彻底解决 unknown[] 报错）
      let articleList: Article[] = [];
      if (response && typeof response === 'object' && 'data' in response) {
        if (Array.isArray(response.data)) {
          articleList = response.data as Article[];
        }
      } else if (Array.isArray(response)) {
        articleList = response as Article[];
      }

      setArticles(articleList);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : '获取文章列表失败';
      console.error('❌ 获取文章失败', err);
      setError(message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchArticles();
  }, []);

  const handleDelete = async (id: string) => {
    if (!confirm('确定删除这篇文章吗？')) return;
    alert(`文章 ${id} 已删除（演示，后续对接真实删除接口）`);
    fetchArticles();
  };

  const getStatusBadge = (status: Article['review_status']) => {
    const map = {
      draft: { label: '草稿', color: 'bg-gray-100 text-gray-600' },
      pending: { label: '待审核', color: 'bg-amber-100 text-amber-600' },
      published: { label: '已发布', color: 'bg-emerald-100 text-emerald-600' },
      rejected: { label: '已驳回', color: 'bg-red-100 text-red-600' },
    };
    const info = map[status] || { label: status, color: 'bg-gray-100 text-gray-600' };
    return <span className={`inline-block px-3 py-1 rounded-full text-xs font-medium ${info.color}`}>{info.label}</span>;
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">文章管理</h1>
          <p className="text-gray-500 mt-1">共 {articles.length} 条文章</p>
        </div>
        <button
          onClick={() => alert('后续实现新增文章弹窗')}
          className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-2xl font-medium transition-all"
        >
          <Plus className="w-5 h-5" />
          新增文章
        </button>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-600 px-6 py-4 rounded-2xl">
          {error}
        </div>
      )}

      {loading ? (
        <div className="text-center py-12 text-gray-400">加载中...</div>
      ) : (
        <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
          <table className="w-full">
            <thead className="bg-gray-50 border-b">
              <tr>
                <th className="px-6 py-4 text-left text-sm font-medium text-gray-500">标题</th>
                <th className="px-6 py-4 text-left text-sm font-medium text-gray-500">栏目</th>
                <th className="px-6 py-4 text-left text-sm font-medium text-gray-500">状态</th>
                <th className="px-6 py-4 text-left text-sm font-medium text-gray-500">发布时间</th>
                <th className="px-6 py-4 text-center text-sm font-medium text-gray-500">操作</th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {articles.map((article) => (
                <tr key={article.id} className="hover:bg-gray-50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="font-medium text-gray-900">{article.title}</div>
                    <div className="text-xs text-gray-400">slug: {article.slug}</div>
                  </td>
                  <td className="px-6 py-4 text-sm text-gray-600">示例栏目</td>
                  <td className="px-6 py-4">{getStatusBadge(article.review_status)}</td>
                  <td className="px-6 py-4 text-sm text-gray-500">
                    {article.publish_time ? new Date(article.publish_time).toLocaleDateString('zh-CN') : '未发布'}
                  </td>
                  <td className="px-6 py-4 text-center">
                    <div className="flex items-center justify-center gap-3">
                      <button
                        onClick={() => alert(`编辑文章 ${article.id}`)}
                        className="text-blue-600 hover:text-blue-700"
                      >
                        <Edit className="w-5 h-5" />
                      </button>
                      <button
                        onClick={() => handleDelete(article.id)}
                        className="text-red-500 hover:text-red-600"
                      >
                        <Trash2 className="w-5 h-5" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
